def fig(src,title,caption=''):
 return f'<figure><a href="{src}" target="_blank"><img loading="lazy" src="{src}" alt="{html.escape(title)}"></a><figcaption><b>{html.escape(title)}</b>{html.escape(caption)}</figcaption></figure>'
refs={'maker':'murderbird-unified-maker-clean-candidate-2026-09-06.png','mechanic':'murderbird-unified-mechanic-candidate-2026-09-06.png','builder':'murderbird-unified-master-candidate-03-2026-09-06.png'}
labels={'maker':'I · Maker','mechanic':'II · Mechanic','builder':'III · Advanced'}
