for era in refs:
 parts.append(f'<section id="{era}"><h2>{labels[era]}</h2><p>'+{'maker':'Newly fabricated, before immersion. Individual formed plates, passive bearings and dark optic recesses. External controls remain visible.','mechanic':'The inherited shell after aging and repair. Iron braces and replacement strips retain visible edges and different fasteners. The optic remains unlit.','builder':'The aged body and repair landmarks remain. Protected upgrades, separate power and processing, and a restrained amber lens carry the new capability.'}[era]+'</p><div class="pair">')
 parts.append(fig('../../img/library/'+refs[era],'Selected era reference','Perspective illustration; exact hidden construction is not established.'))
 parts.append(fig(era+('-reference-angle.png' if era!='builder' else '-authoring-neutral.png'),labels[era]+' · neutral source-comparison angle','Proposed geometry, viewed from the same side as the selected illustration; perspective is not an exact dimensional match.'))
 parts.append('</div><div class="gallery">')
 for p in sorted(list(OUT.glob(era+'-*.png'))+(list(OUT.glob('advanced-*.png')) if era=='builder' else [])):
  if 'authoring' in p.name or 'reference-angle' in p.name:continue
  parts.append(fig(p.name,p.stem.replace(era+'-','').replace('-',' '),'Browser capture of this local build.'))
 parts.append('</div></section>')
views=[]
for v in ['three-quarter','front','side','rear','head']:
 views.append(f'<h3>{v.replace("-"," ").title()}</h3><div class="pair">'+fig('../structural-reconciliation-v1/after-'+v+'.png','Structural v1 · before','Same orthographic camera and scale.')+fig('exterior-clay-'+v+'.png','Exterior v1 · geometry','Neutral clay isolates silhouette and construction.')+'</div>')
